-- Run after account_profile.sql, only in the disposable PostgreSQL fixture.
select public.profile_test_assert((select count(*) = 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'update_my_profile'), 'one RPC signature avoids PostgREST ambiguity');
set role authenticated;
select set_config('request.jwt.claim.sub', '22222222-2222-2222-2222-222222222222', false);
select public.profile_test_assert(public.fetch_or_create_my_profile('22222222-2222-2222-2222-222222222222')->>'bio' = '', 'new bio defaults to empty');
select public.profile_test_reject($q$select bio from public.public_profiles$q$);
select public.profile_test_assert(public.update_my_profile('22222222-2222-2222-2222-222222222222', '시오라멘', p_bio => repeat('🍜', 50))->>'bio' = repeat('🍜', 50), 'fifty Unicode codepoints accepted');
select public.profile_test_assert(public.fetch_or_create_my_profile('22222222-2222-2222-2222-222222222222')->>'bio' = repeat('🍜', 50), 'bio persists on fetch');
select public.profile_test_assert(public.update_my_profile('22222222-2222-2222-2222-222222222222', '시오라멘', null, false)->>'bio' = repeat('🍜', 50), 'legacy four-argument update preserves bio');
select public.profile_test_assert(public.update_my_profile('22222222-2222-2222-2222-222222222222', '시오라멘', null, false, null)->>'bio' = repeat('🍜', 50), 'explicit null fifth argument preserves bio');
select public.profile_test_reject($q$select public.update_my_profile('22222222-2222-2222-2222-222222222222', '시오라멘', p_bio => repeat('🍜', 51))$q$);
select public.profile_test_reject(format('select public.update_my_profile(%L, %L, p_bio => %L)', '22222222-2222-2222-2222-222222222222', '시오라멘', '첫 줄' || chr(separator) || '둘째 줄'))
from unnest(array[10, 13, 11, 12, 133, 8232, 8233]) separator;
select public.profile_test_reject($q$select public.update_my_profile('11111111-1111-1111-1111-111111111111', '시오라멘', p_bio => 'other owner')$q$);
reset role;
update public.public_profiles set approved_at = now() where user_id = '22222222-2222-2222-2222-222222222222';
set role authenticated;
select public.update_my_profile('22222222-2222-2222-2222-222222222222', '시오라멘', p_bio => repeat('🍜', 50));
reset role;
select public.profile_test_assert((select approved_at is not null from public.public_profiles where user_id = '22222222-2222-2222-2222-222222222222'), 'unchanged bio preserves approval');
set role authenticated;
select public.profile_test_assert(public.update_my_profile('22222222-2222-2222-2222-222222222222', '시오라멘', p_bio => '')->>'bio' = '', 'empty bio clears stored value');
reset role;
select public.profile_test_assert((select approved_at is null and accepted_at is null and accepted_guidelines_version is null from public.public_profiles where user_id = '22222222-2222-2222-2222-222222222222'), 'bio change resets approval and preserves consent');
select public.profile_test_reject($q$update public.public_profiles set bio = E'one\ntwo' where user_id = '22222222-2222-2222-2222-222222222222'$q$);
set role authenticated;
select set_config('request.jwt.claim.sub', '11111111-1111-1111-1111-111111111111', false);
select public.profile_test_reject($q$select public.update_my_profile('11111111-1111-1111-1111-111111111111', '시오라멘', p_bio => 'suspended')$q$);
set role anon;
select public.profile_test_reject($q$select public.update_my_profile('11111111-1111-1111-1111-111111111111', '시오라멘', p_bio => 'anonymous')$q$);
reset role;
